#[derive(Clone, Copy)]
enum FileAction {
    Copy,
    Cut,
    Paste,
    Rename,
    Delete,
    NewFolder,
}

pub struct PixelView {
    registry: Arc<Registry>,
    thumbs: ThumbBuilder,

    folder: Option<PathBuf>,
    all_entries: Vec<Entry>, // raw scan; `entries` is the filtered + sorted view of it
    entries: Vec<Entry>,
    thumb_tex: HashMap<PathBuf, egui::TextureHandle>,
    img_meta: HashMap<PathBuf, ImgMeta>,
    sauce_cache: HashMap<PathBuf, Option<crate::sauce::Sauce>>, // parsed SAUCE per path
    pdf_cache: HashMap<PathBuf, Option<crate::decode::PdfMeta>>, // lazy PDF metadata for Details
    pdf_view: Option<PdfView>, // in-app multi-page PDF viewer state (None = not viewing a PDF)
    xmind_view: Option<XMindView>, // in-app multi-sheet XMind viewer state (None = not viewing one)
    three_d: Option<ThreeDView>, // in-app interactive 3D model viewer (None = not viewing a mesh)
    // Pseudo-vector zoom: a deferred request to re-rasterize the open XMind/PDF at this
    // longest-side px (set while drawing when the texture is being upscaled; applied after).
    want_rerender: Option<u32>,
    audio_cache: HashMap<PathBuf, Option<crate::decode::AudioInfo>>, // lazy audio metadata
    tracker_cache: HashMap<PathBuf, Option<crate::libxmp::TrackerInfo>>, // lazy module structure
    sf_cache: HashMap<PathBuf, Option<crate::soundfont::SoundFontInfo>>, // lazy .sf2 directory info
    sfz_cache: HashMap<PathBuf, Option<crate::sfz::SfzInfo>>,        // lazy .sfz directory info
    dls_cache: HashMap<PathBuf, Option<crate::dls::DlsInfo>>,        // lazy .dls directory info
    xi_cache: HashMap<PathBuf, Option<crate::xi::XiInfo>>,           // lazy .xi instrument info
    audio_player: Option<AudioPlayer>, // in-app play/pause/seek preview (rodio), None = idle
    audio_decode_cache: Vec<(PathBuf, u64, DecodedAudio)>, // LRU of decoded audio (key: path+sig)
    audio_loading: Option<AudioLoading>, // a background audio decode in flight (spinner while pending)
    audio_autoplay: bool,                // start playing on select + loop until stopped (persisted)
    wave_drag: Option<WaveDrag>,         // active waveform-editor drag (transient)
    wave_drag_big: bool, // which waveform owns the active drag (big central vs. compact Details) —
    // the SAME audio is drawn in BOTH at once, sharing `wave_drag`; only the owner may process/commit
    // it, else the non-owner maps the global pointer through its own (far-away) rect and clobbers it
    nudge_lock: Option<(Edge, f32)>, // (edge, last wheel-nudge time): keep nudging it as it drifts
    wave_view: Option<(f32, f32)>, // zoomed view window (start,end secs); None = whole file (transient)
    env_edit: bool, // amp-envelope edit mode: overlay the ADSR curve + draggable handles on the
    // waveform while drilled into a pad (transient; reset on Back / navigation)
    env_grid: bool, // draw a BPM beat-division grid in the envelope editor (persisted)
    env_snap: bool, // snap dragged envelope nodes to that grid (persisted)
    env_target: EnvTarget, // which modulation target the overlay edits (Amp/Pitch/Cutoff/Res; transient)
    env_user_presets: Vec<(String, [f32; 8])>, // user-saved envelope shapes (name → 8 values; persisted)
    env_preset_name: String,                   // in-progress "save preset as" name (transient)
    sel_undo: Vec<(f32, f32)>, // selection history: previous (start,end)s for undo (transient)
    sel_redo: Vec<(f32, f32)>, // undone selections, for redo (transient)
    sel_undo_pending: Option<(f32, f32)>, // pre-change selection, pushed to sel_undo on commit
    play_from_mark: Option<f32>, // where the last middle-click started playback (neon ▶ marker)
    zoom_edit_pct: u32, // "Zoom Edit %": magnification of the edge inset (0 = off); persisted
    wave_amp: f32,      // waveform vertical magnification (1 = normal); persisted
    // Transient / BPM / musical-grid state (item 10). Marks are detected times (secs), cached for
    // the current buffer and recomputed when the sensitivity or buffer changes.
    transients_on: bool,  // detect + draw transient guideline markers (persisted)
    snap_transient: bool, // snap selection edges to the nearest transient (persisted)
    transient_sens: f32,  // detection sensitivity 0..1 (persisted)
    transient_marks: Vec<f32>, // detected transient times (secs), for markers + Alt-snap
    transient_dirty: bool, // recompute marks next frame (buffer/sensitivity changed)
    bpm: f32,             // tempo for the musical grid (persisted)
    musical_on: bool,     // draw a musical (beat-division) grid (persisted)
    musical_div: u8,      // 0=whole 1=half 2=quarter 3=eighth 4=sixteenth 5=32nd (persisted)
    audio_octave: i32,    // onscreen-keyboard octave offset (transient)
    audio_volume: f32,    // master playback volume 0..1 (menu-bar slider, persisted)
    audio_muted: bool,    // master mute (menu-bar speaker toggle, persisted)
    // 4×4 sample-pad grid (a mini Battery) — a persistent, cross-file "kit" of favorite samples
    // for quick auditioning. Always length 16. Metadata persists (PADS_KEY); each pad's audio is
    // a WAV under `<data_dir>/pads/` (write-through). Saveable/loadable as a named `.pvkit`.
    pads: Vec<Pad>,
    pad_base_note: i32, // base MIDI note for auto pad-mapping (default 48 = C3, chromatic up); persisted
    kit_global_vel: bool, // kit-wide fixed velocity: overrides every pad's per-pad velocity setting
    kit_global_vel_amt: u8, // the fixed velocity (0..127) used for all pads when global vel is on
    audio_left_w: f32,  // width of the resizable sample-list pane in the big audio view; persisted
    audio_wave_h: f32,  // height of the resizable waveform in the big audio view; persisted
    audio_kb_h: f32, // height of the resizable onscreen keyboard in the big audio view; persisted
    pad_assign: Option<usize>, // "MIDI-learn" mode: the next note-on assigns this pad's note (transient)
    // Live-edit re-trigger of a drilled-in pad's LOOPING voice: `pad_last_vel[i]` remembers the raw
    // velocity a pad was fired at (so a re-fire matches level); `pad_edit_sig` = (pad, param hash)
    // of the sounding loop last frame; `pad_edit_dirty` is set when it changes and consumed on
    // mouse-release to re-fire — so tweaking loop/pitch/filter/envelope is heard without a re-trigger,
    // without restarting every drag frame. All transient. See `poll_pad_retrigger`.
    pad_last_vel: [u8; PAD_COUNT],
    pad_edit_sig: Option<(usize, u64)>,
    pad_edit_dirty: bool,
    edit_focus: EditFocus, // what the waveform editor is pointed at (Song / Sample / a Pad drill-in)
    editor_stash: Option<EditorStash>, // saved editor state during a pad drill-in (restored on Back)
    note_flash: HashMap<i32, f32>, // MIDI note → last-played ctx time, for the keyboard key lights (transient)
    last_midi_t: f32, // ctx time of the last hardware-MIDI event, for the activity LED (transient)
    kit_name: String, // current kit's name ("Untitled" by default; persisted)
    kit_editor: bool, // standalone Sample-Pads view (no audio file needed); transient
    midi_follow: bool, // note-triggered pads auto-drill into the editor (persisted)
    kit_map_lock: bool, // lock the pad→MIDI-note map (MIDI-learn won't reassign); persisted
    octave_lock: bool, // lock the onscreen-keyboard octave across editor views (persisted)
    data_dir: PathBuf, // eframe data dir (pads WAVs + saved kits live under here)
    // Hardware MIDI controller → play the loaded sample. The callback runs on midir's thread
    // and sends note events over `midi_rx`; `midi_conn` must be kept alive (drop = close).
    midi_rx: Option<std::sync::mpsc::Receiver<MidiNoteEvent>>,
    midi_conn: Option<midir::MidiInputConnection<std::sync::mpsc::Sender<MidiNoteEvent>>>,
    // A clone of the egui `Context`, so the MIDI input callback (on midir's own thread) can wake
    // egui with `request_repaint()` — otherwise a note-on while the UI is idle isn't processed
    // by `poll_midi` until the next repaint (e.g. a mouse move).
    egui_ctx: egui::Context,
    midi_port: Option<String>, // chosen MIDI input device name (persisted)
    midi_ports: Vec<String>,   // last-enumerated device names (for the picker combo)
    midi_sf: Option<PathBuf>, // General MIDI SoundFont for playing .mid files (persisted; None = auto-detect)
    midi_sf_cache: Option<(PathBuf, std::sync::Arc<rustysynth::SoundFont>)>, // loaded GM SoundFont (once/session)
    palettes: HashMap<PathBuf, Option<Vec<[u8; 4]>>>, // details swatches; None = too many colors
    thumb_rgba: HashMap<PathBuf, (usize, usize, Vec<u8>)>, // thumb CPU pixels (for grid recolor)
    grid_recolor: HashMap<PathBuf, (String, egui::TextureHandle)>, // recolored grid tiles, per recolor key
    folder_info: HashMap<PathBuf, FolderInfo>, // cached montage previews + counts per folder

    mode: Mode,
    selected: usize,
    selection: HashSet<PathBuf>, // keyed by path so it survives re-sorting/filtering
    anchor: Option<usize>,
    hovered: Option<usize>,

    // sort & filter (Phase 5)
    sort_key: SortKey,
    sort_desc: bool,
    dirs_first: bool,
    min_rating: u8,
    // Show dotfiles / hidden entries in the grid + table (`.` hotkey / View menu).
    // A *view* filter (like `min_rating`): the scan always keeps hidden entries in
    // `all_entries`, so toggling is an instant `rebuild_view`, never a re-scan.
    show_hidden: bool,
    // Cross-platform ratings sidecar — the source of truth for virtual art (inside
    // archives / 16colo.rs) that can't carry a `user.baloo.rating` xattr.
    ratings: crate::ratings::RatingStore,
    // View history (visited state + counts + last-viewed), SQLite-backed. None if the
    // db couldn't be opened — the app then runs with view-tracking disabled.
    viewdb: Option<crate::viewdb::ViewDb>,

    // chrome (Phase 6 + round 2)
    show_explorer: bool,
    show_details: bool,
    show_recolor: bool,                      // the Recolor dock pane
    recolor_grid: bool,                      // apply the active recolor to grid thumbnails too
    last_inspected: Option<PathBuf>,         // sticky target for details/recolor in grid mode
    custom_palette: Option<Vec<[u8; 4]>>,    // a generated/edited palette (e.g. Random)
    flash: Option<[u8; 4]>,                  // swatch held down: highlight this color
    editing_color: Option<(usize, [u8; 4])>, // swatch right-click: editing palette[idx]
    swatch_rect: Option<egui::Rect>, // screen rect of the palette swatch row (Edit-color anchor)
    adjust: Adjust,                  // tone adjustments applied before the palette map
    explorer_filter: String,         // folder-tree search box (runtime only)
    colo_search: String,             // 16colo.rs nav-bar search box (runtime only)
    explorer_tab: u8,                // 0 = Places, 1 = Folders
    places_tab: u8, // Places sub-tab: 0 = Local, 1 = 16colo.rs, 2 = Kits, 3 = Samples, 4 = PixelFX
    // PixelFX presets: saved snapshots of the whole recolor stack, recalled from the
    // Places → PixelFX sub-tab. Save/apply/rename/colorize/remove.
    pixelfx: Vec<FxPreset>,
    pixelfx_name: String,                    // "save current" name buffer
    pixelfx_folder: String, // "save into folder" buffer (empty = top level); also the "＋ new folder" target in Move-to
    pixelfx_rename: Option<(usize, String)>, // inline-rename buffer (transient)
    // User-managed "Samples" locations (name, dir, optional color tag) — quick jumps to sample
    // folders to drag/assign into pads. Add/rename/colorize/remove from the Samples sub-tab.
    sample_places: Vec<(String, PathBuf, Option<[u8; 3]>)>,
    sample_rename: Option<(usize, String)>, // inline-rename buffer for a Samples place (transient)
    sample_browse: Option<PathBuf>, // an opened Samples location → inline file explorer (transient)
    sample_sel: Option<PathBuf>, // highlighted sample row (selection + hot-swap cursor); transient
    sample_focus: bool, // the Samples pane holds keyboard focus (arrows navigate it) — a Renoise-style
    // click-to-focus so hot-swap keys never clash with grid/viewer handlers; a focus outline shows it
    pad_list_focus: bool, // the kit-editor "Pads (N)" list holds keyboard focus (↑/↓ drill pads, Enter
    // opens the sample browser for the pad) — mutually exclusive with `sample_focus`; a focus outline shows it
    hotswap_pad: Option<usize>, // pad being auditioned/hot-swapped from the Samples browser (Up/Down
    // audition on it, Right plays, Enter assigns, Esc reverts) — its pre-swap state is `hotswap_orig`
    hotswap_orig: Option<Pad>, // the hot-swapped pad's pre-swap state, restored on Escape (abort)
    editor_source: Option<PathBuf>, // a sample loaded into the editor from the browser (for load_pad)
    pad_rename: Option<(usize, String)>, // inline-rename buffer for pad i's name (transient)
    show_hotkeys: bool,
    show_prefs: bool,
    show_associations: bool, // the View → Associations editor window is open
    assoc_tab: u8,           // Associations window tab: 0 = Files, 1 = Folders
    // Optional format "plugins" (Preferences checkboxes; persisted). Off = that file type
    // drops out of the listing + won't decode. Applied to the shared `Registry`.
    plugin_pdf: bool,
    plugin_audio: bool,
    plugin_code: bool,
    plugin_3d: bool, // 3D models (.obj/.stl/.ply/.gltf/.glb/.dae) → thumbnail + 3D viewer
    plugin_video: bool, // video (mp4/mkv/webm/…) → ffmpeg frame thumbnail + in-app player
    // User-defined external "Open in…" programs by file type (persisted).
    openers: Vec<Opener>,
    assoc_selected: usize, // selected opener row in the Associations editor (Files tab)
    // User-defined "Open folder in…" programs (persisted). Same shape as `openers` but the
    // `exts` field is unused — a folder action runs on a directory, not a file type.
    folder_actions: Vec<Opener>,
    folder_act_selected: usize, // selected row in the Associations editor's Folders tab
    // Decoded icon textures for openers + folder actions (keyed by icon path; `None` = failed).
    opener_icons: HashMap<PathBuf, Option<egui::TextureHandle>>,

    // preferences (round 2 #10)
    theme: u8,              // 0 = dark, 1 = light
    grid_gap: f32,          // horizontal spacing between grid tiles, in points
    grid_gap_y: f32,        // vertical spacing between grid rows, in points
    grid_tile_border: bool, // draw a border + padding around each grid tile (persisted)
    caption_fields: u16,    // bitmask: what to show under each grid thumbnail
    // Per-category grid-tile backgrounds: a subtle accent behind folder / archive /
    // sample-bank tiles so container kinds read at a glance. Accents are blended into
    // the theme background (`tile_category_bg`); off = the plain default everywhere.
    tile_bg_enabled: bool,
    tile_bg_folder: [u8; 3],    // real directories
    tile_bg_archive: [u8; 3],   // .zip/.lha/.arj/… browsable archives
    tile_bg_container: [u8; 3], // sample banks: .sf2/.sfz/.dls/.xi
    // Draggable thumbnail-area heights (points) for the Details + Recolor panes: the preview
    // *fits inside* this fixed band instead of dictating the pane's height. Persisted.
    details_thumb_h: f32,
    recolor_thumb_h: f32,
    quantize_on: bool,       // details palette: reduce to N colors (median cut)
    quantize_n: usize,       // target color count when reducing
    dither_method: u8,       // index into thumb::DITHER_NAMES (0 = none)
    dither_amount: f32,      // 0..1 dither strength
    dither_custom: Vec<u32>, // custom ordered-dither threshold matrix (row-major)
    dither_custom_n: usize,  // custom matrix dimension (n×n; 2/4/8)
    dither_scale_x: usize,   // ordered-dither cell WIDTH in px (≥1; "zoom" the pattern)
    dither_scale_y: usize,   // ordered-dither cell HEIGHT in px (≥1)
    dither_scale_lock: bool, // lock the dither cell square (scale_x == scale_y)
    pixelate_h: f32,         // Pixelate block HEIGHT in px (width = adjust.pixelate); <2 = square
    pixelate_lock: bool,     // lock the pixelate block square (height == width)
    // Resize/resample preview: downsample the art to a fraction of native, run the
    // whole pipeline (dither/palette) at that lower resolution, then nearest-upscale
    // back to native — so it displays at the SAME screen size but shows the
    // degradation, and single-pixel dither operates at the reduced resolution.
    resize_on: bool,                                        // is the resample active?
    resize_fx: f32,                                         // width factor  (0,1] of native
    resize_fy: f32,                                         // height factor (0,1] of native
    resize_lock: bool,                                      // lock aspect (fx == fy)
    scale_algo: crate::scale::Scaler, // pixel-art upscaler applied before the pipeline
    postfx: PostFx,                   // CRT post-filters (scanlines/glow/vignette/phosphor markers)
    balance_color: [u8; 3],           // color-balance op: ±offset color (128 = neutral)
    balance_strength: f32,            // color-balance op: 0..1 amount
    balance_hex: String,              // live buffer for the hex paste field
    quantize_cache: Option<(PathBuf, usize, Vec<[u8; 4]>)>, // memoized reduction
    // Colors to feed the Reduce median-cut when the image has too many colors to
    // extract a swatch palette (`palettes[path]` is `Some(None)`): its pixels
    // sampled once from a thumbnail decode, cached so changing N doesn't re-decode.
    reduce_src: Option<(PathBuf, Vec<[u8; 4]>)>,
    // GPL palette library (palette-swap preview).
    palette_dir: PathBuf,                            // where the .gpl files live
    palette_files: Vec<PathBuf>,                     // scanned *.gpl in palette_dir
    palette_favorites: Vec<PathBuf>,                 // pinned palettes (quick buttons)
    selected_palette: Option<PathBuf>,               // active swap palette (None = Reduce/Original)
    loaded_palettes: HashMap<PathBuf, Vec<[u8; 4]>>, // parsed .gpl cache
    // Recolored preview for the details thumbnail: decoded source pixels (per path)
    // + the remapped texture (keyed by a recolor string), so it updates live.
    preview_src: Option<(PathBuf, usize, usize, Vec<u8>)>,
    preview_tex: Option<(PathBuf, String, egui::TextureHandle)>,
    // hotkeys (round 2 #12)
    keymap: HashMap<Action, egui::Key>,
    rebinding: Option<Action>, // the action awaiting a new key, if any

    // single-view state
    full_tex: Option<(PathBuf, TiledTexture)>,
    full_src: Option<(PathBuf, [usize; 2], Vec<u8>)>, // decoded full pixels (for reduction)
    full_reduced: Option<(PathBuf, String, TiledTexture)>, // remapped, per (path,recolor)

    // --- Image compare (side-by-side diff) -------------------------------------
    // The two files chosen from the grid/table context menu (Compare ▸ source / diff).
    compare_source: Option<PathBuf>,
    compare_diff: Option<PathBuf>,
    compare_color: [u8; 3],            // diff-highlight colour (persisted)
    compare_hex: String,               // hex entry buffer for the colour field (transient)
    compare_opacity: f32,              // diff overlay opacity 0..1 (persisted)
    compare_tolerance: u8,             // per-channel diff tolerance, 0 = exact match (persisted)
    compare_swapped: bool,             // swap which side shows source vs diff (transient)
    compare_sync: bool,                // pan/zoom moves both panes together (persisted)
    compare_name: String,              // "save as…" name buffer (transient)
    compare: Compare,                  // transient runtime (textures, per-pane view, overlay)
    saved_compares: Vec<SavedCompare>, // saved, recallable comparisons (persisted)

    anim: Option<AnimState>,         // Some when viewing an animated GIF
    hover_anim: Option<AnimState>,   // the hovered grid GIF, playing in its tile
    video_hover: Option<VideoStrip>, // the hovered grid video's scrub strip (pointer-x → frame)
    video_hover_frac: f32, // current scrub position (0..1) — mirrored into the Details preview
    video_player: Option<crate::video::VideoPlayer>, // Some when viewing a video (frame stream + soundtrack)
    video_loading: Option<crate::video::VideoLoading>, // a background video open in flight (spinner)
    video_tex: Option<egui::TextureHandle>, // the current video frame, uploaded on the UI thread
    video_recolor_key: Option<String>, // recolor pipeline key last applied → re-colorize a PAUSED frame when it changes
    recolor_playback: bool, // apply the recolor pipeline to live video frames? off = raw = faster fps (persisted)
    show_fps: bool,         // overlay a UI-fps / video-fps meter on the video (persisted)
    // FPS meter accumulators (not persisted): UI repaints + displayed video frames per window.
    fps_accum_t: f32,
    fps_ui_frames: u32,
    fps_video_frames: u32,
    fps_ui_val: f32,
    fps_video_val: f32,
    fps_upload_ms: f32, // ms spent building+uploading the frame texture (last frame)
    fps_blit_ms: f32,   // ms spent in draw_image_view (last frame)
    fps_total_ms: f32,  // ms spent in draw_video_ui total (last frame)
    video_markers: Vec<VideoMarker>, // chapter markers (timecode + title + notes) from the `.md`
    video_md_header: String,         // any `.md` text before the first marker (preserved on save)
    video_marker_sel: Option<usize>, // the marker whose notes editor is open (click to toggle)
    video_marker_focus: bool,        // request focus on a freshly-added marker's title field
    video_speed: f32,                // remembered video playback speed (this session)
    video_scrub: Option<f32>,        // seek-bar drag position (Some while dragging the scrubber)
    video_scrub_t: f64, // last scrub-preview time (throttles ffmpeg respawns while dragging)
    video_seek_input: String, // the "go to time" text field (mm:ss / hh:mm:ss)
    video_trim_in: Option<f32>, // trim/export In point (seconds); i-key or ⟦In
    video_trim_out: Option<f32>, // trim/export Out point (seconds); o-key or Out⟧
    player: Option<Player>, // baud-rate playback for the open text/RIP art (ANSImation)
    zoom: f32,
    zoom_lock: bool, // viewer: snap zoom to 100% steps (¼ steps below 100%)
    offset: egui::Vec2,
    view_to_top: bool, // viewer: a freshly opened image starts at its top-left (set on
    // load, applied once its pixel size is known in draw_image_view)
    fit_width_on_open: bool, // viewer: cap a freshly opened text-mode image's zoom so its
    // full width fits the viewport (wide ANSIs don't clip)
    nav_drag: bool, // viewer: the active drag began on the navigator minimap, so it
    // stays in navigator mode even if the cursor leaves the strip
    // viewer: a crisp minimap built from the full-res pixels at the strip's device
    // resolution (path, [w,h] device px, texture), rebuilt on image/size change.
    minimap: Option<(PathBuf, [usize; 2], egui::TextureHandle)>,
    // viewer: during baud playback, the typing cursor's source-Y (px) to keep at the
    // bottom of the viewport (BBS-style auto-scroll); None when not playing/scrolling.
    play_autoscroll: Option<f32>,
    tile_mode: bool, // viewer: tile the image across the whole window (texture testing)
    fit_requested: bool, // viewer: apply fit-to-window on the next draw
    fit_mode: bool,  // viewer: sticky — re-fit every newly loaded image (persisted)
    // Text-mode / scene art (ANSI/XBin/BIN/…) renders at a tiny native 8×16 px per
    // cell, so a true 1:1 (100%) view is unreadably small. We give it its own
    // remembered zoom (default 3×, the "real text screen" feel) kept independent of
    // the raster-image zoom, plus an optional non-square CRT aspect stretch.
    viewing_textmode: bool, // is the currently-loaded viewer image text-mode art?
    crt_aspect: bool,       // stretch text-mode art ~1.2× vertically (4:3 CRT look)
    font_9px: bool,         // render the VGA font in a 9-dot cell (true DOS width)
    baud_ansi: Baud,        // simulated modem speed for ANSImation playback (persisted)
    baud_rip: Baud,         // simulated modem speed for RIP playback — independent (persisted)
    crt_scanline_dark: f32, // retro-monitor scanline darkness, 0 = off (persisted)
    crt_scanline_scale: bool, // scale scanline spacing with the zoom (persisted)
    glow: bool,             // phosphor-glow bloom around bright pixels (persisted)
    glow_amt: f32,          // phosphor-glow intensity (persisted)
    black_bg: bool,         // fill the viewer background black instead of dark grey (persisted)
    // Transparency backdrop: what shows *through* an image's transparent pixels in the
    // viewer (checkerboard or a solid colour of the user's choosing). All persisted.
    transp_solid: bool,        // false = checkerboard, true = solid `transp_color`
    transp_checker_size: u8,   // 0 = Small, 1 = Medium, 2 = Large (checker cell in device px)
    transp_checker_a: [u8; 3], // the two alternating checker colours
    transp_checker_b: [u8; 3],
    transp_color: [u8; 3], // the solid backdrop colour
    // A 2×2 Repeat-wrapped checker texture, rebuilt when the two colours change (runtime).
    checker_tex: Option<(egui::TextureHandle, [u8; 3], [u8; 3])>,
    // 3D viewer "scene setup" (persisted): shading, light direction, background.
    td_shade: u8,           // bitmask: bit0 = Textured base, bit1 = Wireframe overlay
    td_wire_color: [u8; 3], // wireframe overlay line colour
    td_light_yaw: f32,      // view-space key-light azimuth
    td_light_pitch: f32,    // view-space key-light elevation
    td_bg: [u8; 3],         // 3D viewport background colour
    // Metadata OSD: a fading info overlay shown on each newly opened image.
    osd_enabled: bool,                         // show the OSD at all (persisted)
    osd_position: u8, // anchor 0..=7: TL,T,TR,L,R,BL,B,BR (3×3 grid, no center) (persisted)
    osd_secs: f32,    // how long it holds at full opacity before fading (persisted)
    osd_t: f32,       // animation clock since the current image opened (runtime)
    osd_rect: Option<egui::Rect>, // last-painted OSD bounds (for hover-to-pin)
    osd_links: Vec<(egui::Rect, PathBuf)>, // clickable field rects → open_folder target
    osd_close: Option<egui::Rect>, // the [×] dismiss button's last-painted rect
    osd_dismissed: bool, // [×] clicked → hide the OSD for *this* image (reset on next load)
    scanline_tex: Option<egui::TextureHandle>, // lazily-built 1×3 scanline pattern
    auto_next: bool,  // slideshow: auto-advance to the next file after a delay (persisted)
    auto_next_secs: u8, // slideshow delay in seconds: 1/3/5/10 (persisted)
    auto_next_dwell: f32, // slideshow: seconds the current (settled) file has been shown
    auto_paused: bool, // slideshow paused by a user interaction (scroll/key/drag); not persisted
    immersive: bool,  // F11 fullscreen: hide all bars/UI, show only the art
    // DEBUG_MODE=true: dock the window to the bottom-right corner on startup (so a dev test
    // instance stays out of the way). Consumed once the monitor size is known. Not persisted.
    debug_dock_pending: bool,
    // Window geometry persistence: `win_geom` = the last-seen [x, y, w, h] (outer position + inner
    // size), captured each frame and written in `save()`. `restore_geom` = the persisted geometry
    // to reapply on the first frame (None in DEBUG_MODE — the dock wins there).
    win_geom: Option<[f32; 4]>,
    restore_geom: Option<[f32; 4]>,
    // Window title bar: when on, the open folder/file's display path is shown after "pixelview";
    // the GUI zoom % (Ctrl +/-) is always appended in parens when it isn't 100%. `title_last`
    // dedupes so we only push a `ViewportCommand::Title` when the string actually changes.
    title_show_path: bool,
    title_last: String,
    idle_t: f32,   // seconds of mouse stillness (immersive cursor auto-hide)
    shuffle: bool, // screensaver: at a pack's end, load another random pack (persisted)
    // screensaver: a worker picking a random 16colo.rs pack → (year, name, download URL)
    random_rx: Option<std::sync::mpsc::Receiver<RandomPick>>,
    pending_autoplay: bool, // open the first art file once a (random) pack finishes mounting
    textmode_zoom: f32,     // remembered viewer zoom for text-mode art (persisted)
    raster_zoom: f32,       // remembered viewer zoom for ordinary raster art (persisted)
    adjust_drag: Option<usize>, // colorizer: order index being drag-reordered

    // navigation (Phase 2 + round 4)
    favorites: Vec<PathBuf>,
    // Optional color tag per favorite/pin (the favorite path → RGB), for organizing
    // Places. Assigned from the favorite's right-click ANSI32 palette. Persisted.
    fav_colors: HashMap<PathBuf, [u8; 3]>,
    // Optional custom display label per pin (path → name); renames the *label* only, not
    // where it points. Falls back to `short_name` when unset. Persisted (`fav_label`).
    fav_names: HashMap<PathBuf, String>,
    // Pin-rename dialog state: (pin path, edit buffer). None = closed. Not persisted.
    fav_rename: Option<(PathBuf, String)>,
    // Top Favorites bar shows only color-tagged favorites (declutter; the rest stay in the
    // Places dock). Falls back to showing all when none are colored. Persisted.
    fav_bar_colored_only: bool,
    path_edit: Option<String>, // Some(..) while the breadcrumb is in type-a-path mode
    focus_path: bool,          // request focus on the path field next frame
    dir_history: Vec<PathBuf>, // visited folders, for mouse back/forward
    dir_pos: usize,
    suppress_history: bool, // set while navigating *via* history (don't re-record)
    archive_mount: Option<ArchiveMount>, // the archive currently browsed as a folder
    // Git status of the current local folder's repo (badge / column / details / tint).
    // Computed off-thread on each folder change; None when not a repo or disabled.
    git_enabled: bool, // Preferences toggle (persisted); off = feature fully inert
    git_info: Option<crate::git::GitInfo>, // current folder's status map (runtime)
    #[allow(clippy::type_complexity)]
    git_rx: Option<std::sync::mpsc::Receiver<(PathBuf, Option<crate::git::GitInfo>)>>, // pending compute
    // Headless-Blender renders of `.blend` files (right-click → Render). The result is cached
    // and becomes the file's thumbnail. Runs off-thread (a render can take a while).
    #[allow(clippy::type_complexity)]
    blend_render_tx: std::sync::mpsc::Sender<(PathBuf, Result<PathBuf, String>)>,
    #[allow(clippy::type_complexity)]
    blend_render_rx: std::sync::mpsc::Receiver<(PathBuf, Result<PathBuf, String>)>,
    blend_render_pending: usize, // in-flight render count (drives the busy spinner)
    // Auto-refresh: (folder, cheap change-signature) + last poll time. When the current
    // local folder's signature changes (a new/removed/modified file), re-scan in place.
    dir_watch: Option<(PathBuf, u64)>,
    dir_watch_at: f64,
    remote_rx: Option<std::sync::mpsc::Receiver<RemoteMsg>>, // pending 16colo.rs fetch
    remote_urls: HashMap<PathBuf, String>,                   // virtual pack path → download URL
    #[allow(clippy::type_complexity)]
    remote_cache: HashMap<PathBuf, (Vec<Entry>, HashMap<PathBuf, String>)>, // year → packs (session)
    scroll_target: Option<usize>, // grid: scroll so this entry index becomes visible
    // Per-folder grid scroll offset (y), so navigating back to a folder restores where
    // you were. egui persists a ScrollArea by id, but the grid shares one id across all
    // folders — so we key the offset by folder path ourselves. `grid_scroll_pending` is
    // the offset to apply *once* on the next grid frame (set on every folder switch).
    grid_scroll: HashMap<PathBuf, f32>,
    grid_scroll_pending: Option<f32>,
    search: Option<String>, // grid: live filename filter (vim-style '/')
    focus_search: bool,
    // advanced recursive search → a "Search results" grid
    show_search: bool,      // the advanced-search panel is open
    focus_adv_search: bool, // request focus on the panel's first field next frame
    search_spec: SearchSpec,
    search_results: Option<Vec<Entry>>, // Some → the grid renders results, not the folder
    search_root: Option<PathBuf>, // folder the active search started from (for relative labels)
    search_rx: Option<std::sync::mpsc::Receiver<SearchMsg>>,
    search_cancel: Option<Arc<std::sync::atomic::AtomicBool>>,
    search_running: bool,
    saved_filters: Vec<(String, SearchSpec)>, // "smart filters": named saved searches (persisted)
    // file operations (round 4)
    clipboard: Option<(Vec<PathBuf>, bool)>, // (paths, is_cut)
    undo_stack: Vec<UndoOp>,
    renaming: Option<(PathBuf, String)>, // (path being renamed, new-name buffer)
    focus_rename: bool,

    status: String,
    want_repaint: bool,

    // Persisted UI scale (egui zoom factor) — what Ctrl +/- adjusts (whole GUI).
    ui_zoom: f32,
    // Persisted on-screen thumbnail tile size in points — Ctrl+wheel in the grid.
    // Independent of `ui_zoom`: this scales tiles only, not the chrome.
    thumb_size: f32,

    // Table view (an alternate renderer for the browse/grid mode — `Mode` stays
    // `Grid`, so selection/ratings/nav/keys all work unchanged). Persisted.
    table_view: bool,
    // Draw subtle row/column dividing lines in the table (zebra is always on). Persisted.
    table_grid: bool,
    // Which optional file columns show in the table (bitmask of TC_*). Persisted.
    table_columns: u16,
    // Which optional 16colo *scene* columns show (bitmask of CS_*). Persisted.
    colo_columns: u16,
    // Per-column width overrides (ColKind as u8 → points), for drag-to-resize. Persisted.
    col_widths: HashMap<u8, f32>,
    // User column order (ColKind as u8) for the file / scene table layouts, from
    // drag-to-reorder; empty = the natural build order. Unknown/new kinds append.
    table_order: Vec<u8>,
    colo_order: Vec<u8>,
    // 16colo.rs flat-piece listing state. `colo_flat` marks the current view as a
    // flattened artist/group/search listing (→ the table shows scene columns). The
    // map carries per-piece metadata keyed by virtual display path (see [`ColoPiece`]).
    colo_flat: bool,
    colo_pieces: HashMap<PathBuf, ColoPiece>,
    // Streaming channel for a piece listing (mirrors `search_rx`): Hit(piece) per match.
    colo_rx: Option<std::sync::mpsc::Receiver<ColoMsg>>,
    colo_cancel: Option<Arc<std::sync::atomic::AtomicBool>>,
    // Remote thumbnail fetcher for 16colo pieces (downloads `tn` PNGs off the UI thread).
    colo_thumbs: RemoteThumbs,
    // Downloaded single-piece files: virtual display path → local cache file, so the
    // viewer can decode a piece opened from the flat listing (see `resolve_local`).
    colo_files: HashMap<PathBuf, PathBuf>,
    // A piece whose `raw` file is downloading so we can open it in the viewer once ready.
    #[allow(clippy::type_complexity)]
    colo_open_rx: Option<
        std::sync::mpsc::Receiver<Result<(PathBuf, PathBuf, Option<crate::sauce::Sauce>), String>>,
    >,
    // When set, the in-flight `colo_open_rx` download is for an external "Open in…" launch
    // `(exec, args, env)` — `poll_colo_open` runs the program instead of opening the viewer.
    pending_external: Option<(String, String, String)>,
    // Status messages from "Download file/pack" save threads (drained into `status`).
    colo_save_rx: Option<std::sync::mpsc::Receiver<String>>,
    // YouTube browsing (mirrors the 16colo source model). `yt_videos` = per-result metadata
    // keyed by virtual display path (`<youtube>/search/<q>/<title> [id].mp4`); `yt_files` maps
    // that path to the downloaded local file (so `resolve_local` + the player find it).
    yt_videos: HashMap<PathBuf, crate::youtube::YtVideo>,
    // A channel's Playlists listing: virtual path → playlist metadata (tile title/thumb/count).
    yt_playlists: HashMap<PathBuf, crate::youtube::YtPlaylist>,
    // Channel id → display name (for the breadcrumb + "Go to channel"), learned from results.
    yt_channel_names: HashMap<String, String>,
    // Last completed YouTube search (path → its result entries + video metadata), so navigating
    // BACK to a search (breadcrumb / back button) restores the results instead of re-running the
    // search. Cleared by F5 so an explicit refresh still re-fetches.
    #[allow(clippy::type_complexity)]
    yt_search_cache: Option<(PathBuf, Vec<Entry>, HashMap<PathBuf, crate::youtube::YtVideo>)>,
    yt_rx: Option<std::sync::mpsc::Receiver<YtMsg>>,
    yt_cancel: Option<Arc<std::sync::atomic::AtomicBool>>,
    yt_files: HashMap<PathBuf, PathBuf>,
    // A video downloading in place so we can open it once ready: live progress + the result.
    yt_open_rx: Option<std::sync::mpsc::Receiver<YtOpenMsg>>,
    yt_open_cancel: Option<Arc<std::sync::atomic::AtomicBool>>, // set → kills yt-dlp (Abort button)
    yt_dl_progress: Option<crate::youtube::DlProgress>, // live %/ETA/speed for the status bar
    // Rich per-video metadata (channel/likes/comments/date/dims) for the Details pane, fetched
    // lazily on a worker (`yt-dlp --dump-json`) when a video is opened. `yt_meta_pending` guards
    // against re-spawning while one fetch is in flight.
    yt_meta: HashMap<PathBuf, crate::youtube::YtMeta>,
    #[allow(clippy::type_complexity)]
    yt_meta_rx: Option<std::sync::mpsc::Receiver<(PathBuf, crate::youtube::YtMeta)>>,
    yt_meta_pending: Option<PathBuf>,
    // Transcript (captions) + comments, fetched on demand for the "Copy for LLM" export.
    yt_info: HashMap<PathBuf, YtInfo>,
    yt_info_rx: Option<std::sync::mpsc::Receiver<(PathBuf, YtInfo)>>,
    yt_info_pending: Option<PathBuf>,
    yt_search: String, // the YouTube Places-tab search box text
    // Browser to pull YouTube cookies from (Preferences) — passed to yt-dlp as
    // `--cookies-from-browser` to clear the "confirm you're not a bot" gate + reach age-gated
    // videos. "" = anonymous (no cookies).
    yt_cookies_browser: String,
    yt_downloaded_ids: std::collections::HashSet<String>, // video ids present in the download dir (→ badge)
    // SteamTube: installed Steam games keyed by virtual path (`<steam>/<Name [appid]>`). Clicking
    // one routes to a YouTube search for the game; right-click launches/opens Steam pages.
    steam_games: HashMap<PathBuf, crate::steam::SteamGame>,
    steam_uninstalled: std::collections::HashSet<PathBuf>, // owned-but-not-installed tiles (→ badge)
    steam_api_key: String, // Steam Web API key (Preferences) for the full owned-games list
    // A game's detail view = a virtual folder of media tiles (screenshots + trailers), keyed by
    // virtual path. Screenshots download to `steam_files`; trailers stream from their HLS URL.
    steam_media: HashMap<PathBuf, crate::steam::MediaItem>,
    steam_files: HashMap<PathBuf, PathBuf>, // downloaded screenshot vpath → local file
    #[allow(clippy::type_complexity)]
    steam_media_rx: Option<std::sync::mpsc::Receiver<(PathBuf, crate::steam::AppMedia)>>,
    steam_open_rx: Option<std::sync::mpsc::Receiver<Result<(PathBuf, PathBuf), String>>>,
    // The currently-open game detail (appid + its fetched media) — powers the Details-pane
    // game info block. `steam_names` maps appid → display name so the breadcrumb shows the
    // game's NAME instead of its numeric appid (seeded from the list + the media fetch).
    steam_detail: Option<(u32, crate::steam::AppMedia)>,
    steam_names: HashMap<u32, String>,
    // Where downloaded YouTube videos are stored (default `<data>/youtube`). Persisted +
    // Preferences-editable so it can live on an external drive; kept separate from the
    // 16colo/HTTP cache since videos get large.
    yt_download_dir: Option<PathBuf>,
    yt_max_height: u32, // YouTube download resolution cap (0 = best); persisted, default 1080
    yt_open_folder_after: bool, // reveal the file in the OS file manager once a download finishes
    // Bulk 16colo.rs download (a whole artist / group / search / pack → a local folder,
    // cache-first). `None` when idle; a progress window shows while `Some`.
    bulk_dl: Option<BulkDownload>,
    // Background pack-SAUCE fetcher for *inspected* (hovered) 16colo pieces. 16colo
    // strips SAUCE from the raw file and the artist/search endpoints omit it, so when
    // the Details panel inspects a piece with no SAUCE we fetch its whole pack's SAUCE
    // (`?sauce=true`) once and seed every file. Shared channel (tx cloned per fetch)
    // since several packs can be in flight; `colo_sauce_done` dedupes per "year/pack".
    // Each seed is (virtual path, optional SAUCE, filesize) — one per file in the pack,
    // so the same fetch backfills both the SAUCE panel and the "0 B" Size (the listing
    // endpoint omits both). filesize is 0 when unknown.
    #[allow(clippy::type_complexity)]
    colo_sauce_tx: std::sync::mpsc::Sender<Vec<(PathBuf, Option<crate::sauce::Sauce>, u64)>>,
    #[allow(clippy::type_complexity)]
    colo_sauce_rx: std::sync::mpsc::Receiver<Vec<(PathBuf, Option<crate::sauce::Sauce>, u64)>>,
    colo_sauce_done: HashSet<String>,
    colo_sauce_pending: usize, // in-flight pack-SAUCE fetches (for the busy spinner)
}

