    #[test]
    fn scene_sort_keys_use_the_piece_map() {
        // Three pieces with distinct artist/year, fed via the colo_pieces map.
        let all = vec![
            img_entry("c.ans", 0, 0),
            img_entry("a.ans", 0, 0),
            img_entry("b.ans", 0, 0),
        ];
        let mut pieces = HashMap::new();
        pieces.insert(PathBuf::from("c.ans"), piece("zinc", "acid", 1994, "p3"));
        pieces.insert(
            PathBuf::from("a.ans"),
            piece("aja", "blocktronics", 2002, "p1"),
        );
        pieces.insert(
            PathBuf::from("b.ans"),
            piece("mistress", "acid", 1991, "p2"),
        );

        // Artist ascending: aja, mistress, zinc.
        let v = sorted_filtered_view(
            &all,
            SortKey::Artist,
            false,
            false,
            0,
            None,
            &HashMap::new(),
            &pieces,
            &HashMap::new(),
        );
        let names: Vec<_> = v.iter().map(|e| e.path.to_str().unwrap()).collect();
        assert_eq!(names, vec!["a.ans", "b.ans", "c.ans"]);

        // Year descending: 2002, 1994, 1991.
        let v = sorted_filtered_view(
            &all,
            SortKey::Year,
            true,
            false,
            0,
            None,
            &HashMap::new(),
            &pieces,
            &HashMap::new(),
        );
        let years: Vec<_> = v.iter().map(|e| pieces[&e.path].year).collect::<Vec<_>>();
        assert_eq!(years, vec![2002, 1994, 1991]);
    }

    #[test]
    fn table_cell_text_scene_vs_file_columns() {
        let e = img_entry("MIDNACD3.ANS", 2048, 3);
        let p = piece("jed", "acid", 1992, "acdu0892");
        // Scene columns: filename / artist / type / year / group / pack.
        assert_eq!(
            table_cell_text(&e, None, Some(&p), ColKind::Name),
            "MIDNACD3.ANS"
        );
        assert_eq!(table_cell_text(&e, None, Some(&p), ColKind::Artist), "jed");
        assert_eq!(table_cell_text(&e, None, Some(&p), ColKind::Type), "ANS");
        assert_eq!(table_cell_text(&e, None, Some(&p), ColKind::Year), "1992");
        assert_eq!(table_cell_text(&e, None, Some(&p), ColKind::Group), "acid");
        assert_eq!(
            table_cell_text(&e, None, Some(&p), ColKind::Pack),
            "acdu0892"
        );
        // File columns: name / type / size / dims / colors.
        let meta = Some(ImgMeta {
            w: 320,
            h: 200,
            colors: Some(16),
        });
        assert_eq!(
            table_cell_text(&e, meta, None, ColKind::Name),
            "MIDNACD3.ANS"
        );
        assert_eq!(table_cell_text(&e, meta, None, ColKind::Type), "ANS");
        assert_eq!(table_cell_text(&e, meta, None, ColKind::Dims), "320×200");
        assert_eq!(table_cell_text(&e, meta, None, ColKind::Colors), "16");
        // A 0-byte entry (folder / virtual dir) hides its size instead of "0 B".
        let zero = img_entry("dir", 0, 0);
        assert_eq!(table_cell_text(&zero, None, None, ColKind::Size), "");
        assert!(!table_cell_text(&e, None, None, ColKind::Size).is_empty());
    }

    #[test]
    fn is_image_ext_recognizes_formats() {
        use std::path::Path;
        assert!(is_image_ext(Path::new("x.png")));
        assert!(is_image_ext(Path::new("X.PCX")));
        assert!(is_image_ext(Path::new("y.aseprite")));
        assert!(is_image_ext(Path::new("z.txt"))); // ASCII/ANSI art
        assert!(is_image_ext(Path::new("noext"))); // extensionless scene/BBS art
        assert!(is_image_ext(Path::new("z.cpp"))); // source code now renders too
        assert!(is_image_ext(Path::new("main.rs")));
        assert!(!is_image_ext(Path::new("z.exe"))); // genuinely non-viewable stays hidden
    }

    #[test]
    fn render_candidate_takes_art_skips_heavy_plugins() {
        use std::path::Path;
        // Scene / raster art a folder scan should convert.
        assert!(is_render_candidate(Path::new("ART.ANS")));
        assert!(is_render_candidate(Path::new("scene.xb")));
        assert!(is_render_candidate(Path::new("logo.rip")));
        assert!(is_render_candidate(Path::new("pic.png")));
        assert!(is_render_candidate(Path::new("noext"))); // extensionless scene art

        // The heavy non-art plugins + source code are skipped for a *folder* scan
        // (an explicitly-named file still gets tried directly, bypassing this filter).
        assert!(!is_render_candidate(Path::new("song.mp3")));
        assert!(!is_render_candidate(Path::new("doc.pdf")));
        assert!(!is_render_candidate(Path::new("main.rs")));
        assert!(!is_render_candidate(Path::new("notes.exe"))); // not viewable at all
    }

    #[test]
    fn upscale_nn_doubles_and_replicates_pixels() {
        // A 2×1 image scaled 2× → 4×2, each source pixel filling a 2×2 block.
        let src = vec![[10, 20, 30, 255], [40, 50, 60, 255]];
        let (bytes, w, h) = upscale_nn(&src, 2, 1, 2);
        assert_eq!((w, h), (4, 2));
        assert_eq!(bytes.len(), (4 * 2 * 4) as usize);
        // Top-left 2 px are the first source color; the next 2 are the second.
        assert_eq!(&bytes[0..4], &[10, 20, 30, 255]);
        assert_eq!(&bytes[4..8], &[10, 20, 30, 255]);
        assert_eq!(&bytes[8..12], &[40, 50, 60, 255]);
        // Row 2 (offset 16 bytes = 4 px * 4) replicates row 1 exactly.
        assert_eq!(&bytes[16..20], &[10, 20, 30, 255]);
    }

